import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"坤","description":"焦氏易林注 - 坤","frontmatter":{"title":"坤","description":"焦氏易林注 - 坤"},"headers":[],"relativePath":"classics/jiaoyilin/002.md","filePath":"classics/jiaoyilin/002.md"}'),l={name:"classics/jiaoyilin/002.md"};function n(d,a,t,s,o,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="坤" tabindex="-1">坤 <a class="header-anchor" href="#坤" aria-label="Permalink to “坤”">​</a></h1><h3 id="坤-1" tabindex="-1">坤 <a class="header-anchor" href="#坤-1" aria-label="Permalink to “坤”">​</a></h3><h3 id="坤之乾" tabindex="-1">坤之乾 <a class="header-anchor" href="#坤之乾" aria-label="Permalink to “坤之乾”">​</a></h3><h3 id="林辭" tabindex="-1">林辭 <a class="header-anchor" href="#林辭" aria-label="Permalink to “林辭”">​</a></h3><p>谷風布氣，萬物出生。萌庶長養，花葉茂盛。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>《詩毛傳》：「谷風，東風也，陰陽和則谷風至。」按：乾納甲故曰東風，又陰變陽故萬物出生而茂盛，坤為萬物、為萌庶也。○盛，從汲古，宋元本皆作成。</p><h3 id="坤之坤" tabindex="-1">坤之坤 <a class="header-anchor" href="#坤之坤" aria-label="Permalink to “坤之坤”">​</a></h3><h3 id="林辭-1" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-1" aria-label="Permalink to “林辭”">​</a></h3><p>不風不雨，白日皎皎。宜出驅馳，通利大道。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>純坤無巽、兌象，故不風不雨，伏乾為日，大明，故曰白日皎皎。震為出、為驅馳、為通、為大塗，言陰極宜陽，覆成震也。</p><h3 id="坤之屯" tabindex="-1">坤之屯 <a class="header-anchor" href="#坤之屯" aria-label="Permalink to “坤之屯”">​</a></h3><h3 id="林辭-2" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-2" aria-label="Permalink to “林辭”">​</a></h3><p>蒼龍單獨，與石相觸。摧折兩角，室家不足。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>震為蒼龍，坤寡故曰單獨。艮為石，在上故龍觸石。艮為角，坤數二，坎折，故曰折其兩角。艮為室家，坤窮故不足。○室家，從宋本，元本作家室。</p><h3 id="坤之蒙" tabindex="-1">坤之蒙 <a class="header-anchor" href="#坤之蒙" aria-label="Permalink to “坤之蒙”">​</a></h3><h3 id="林辭-3" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-3" aria-label="Permalink to “林辭”">​</a></h3><p>城上有烏，自名破家。招呼酖毒，為國患災。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>艮為城、為烏、為家，坎破，故曰破家，坤為自，艮為名也。震為言，艮手，故曰招呼，坤為毒、為災患、為國。○烏，汲古誤馬，依宋本。《左傳》：「城上有烏破家」，疑烏呼聲似之，或當時俗語。患災，從宋元本，汲古作災患。家，音姑，與烏韻。</p><h3 id="坤之需" tabindex="-1">坤之需 <a class="header-anchor" href="#坤之需" aria-label="Permalink to “坤之需”">​</a></h3><h3 id="林辭-4" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-4" aria-label="Permalink to “林辭”">​</a></h3><p>霜降閉戶，蟄蟲隱處。不見日月，與死為伍。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>通晉。坤為霜，艮為戶，坤閉，故曰閉戶。坎伏，故曰蟄蟲、曰隱處。坎月，離日，坎伏，故不見。坤為死。</p><h3 id="坤之訟" tabindex="-1">坤之訟 <a class="header-anchor" href="#坤之訟" aria-label="Permalink to “坤之訟”">​</a></h3><h3 id="林辭-5" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-5" aria-label="Permalink to “林辭”">​</a></h3><p>天之德室，溫仁受福。衣裳所在，兇惡不起。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>乾為天、為德，坎為室，乾為仁，福為衣，伏坤為裳、為兇惡，坤伏坎陷，故不起。</p><h3 id="坤之師" tabindex="-1">坤之師 <a class="header-anchor" href="#坤之師" aria-label="Permalink to “坤之師”">​</a></h3><h3 id="林辭-6" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-6" aria-label="Permalink to “林辭”">​</a></h3><p>皇陛九重，絕不可登。謂天蓋高，未見王公。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>震為帝，故曰皇，震數九，自二至上若階陛然，故曰皇陛九重。坤為重也，震為登，坤閉故不可登。乾為人、為王公，乾伏，故不見。○宋元本三四句倒置，茲依汲古。陛，依宋本，汲古、元本作階。</p><h3 id="坤之比" tabindex="-1">坤之比 <a class="header-anchor" href="#坤之比" aria-label="Permalink to “坤之比”">​</a></h3><h3 id="林辭-7" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-7" aria-label="Permalink to “林辭”">​</a></h3><p>孔德如玉，出於幽谷。飛上喬木，鼓其羽翼，輝光照國。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>艮堅為金玉，坎為幽谷，在上，故曰出。艮為飛、為喬木，艮手為鼓、為羽翼，艮為輝光、為國，《詩小雅》：「其人如玉」，又「伐木丁丁，鳥鳴嬰嬰。出自幽谷，遷於喬木。」○宋元本皆作四句，並三四句為二句，作升高鼓翼，茲依汲古。</p><h3 id="坤之小畜" tabindex="-1">坤之小畜 <a class="header-anchor" href="#坤之小畜" aria-label="Permalink to “坤之小畜”">​</a></h3><h3 id="林辭-8" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-8" aria-label="Permalink to “林辭”">​</a></h3><p>五軛四軏，優得饒有。陳力就列，騶虞悅喜。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>軛，轅端橫木，駕馬領者。軏，《論語》：「小車無軏。」註：軏，轅端持衡者，通《豫》。艮為小木、為軛、為軏，坎數五，震卦數四，故曰五軛四軏。乾富故曰饒有，震為陳列，艮為騶虞。《毛傳》：「騶虞，義獸也。」震為樂，故悅喜。陳樸國雲《禮記射義》：「騶虞，樂官備也」，註：樂官備者，謂騶虞一發，五豝五●，喻得賢眾多也。故焦氏言「陳力就列，騶虞悅喜」也，又按：五軛四軏，言獵車之盛也。○汲古軛作範，軏作軌，依宋元本。優得，依履之艮校，各本皆作復得。又各本下有「四足無角，君子所服。南征述職，以惠我國」四句，與上不韻，顯為衍文，依履之艮刪，宋本則作下履林，按之卦象亦協。</p><h3 id="坤之履" tabindex="-1">坤之履 <a class="header-anchor" href="#坤之履" aria-label="Permalink to “坤之履”">​</a></h3><h3 id="林辭-9" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-9" aria-label="Permalink to “林辭”">​</a></h3><p>敝笱在梁，魴逸不禁。漁父勞苦，焦喉乾口，虛空無有。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>通謙。坤為敝，震為篚筥，為笱，艮為梁，故曰敝笱在梁。坤為魚、為魴，在外故逸。乾為父，坎為勞，兌為口，離火，故曰焦喉乾口。○焦喉，各本皆作連室，皆無末句，依遯之大過校。</p><h3 id="坤之泰" tabindex="-1">坤之泰 <a class="header-anchor" href="#坤之泰" aria-label="Permalink to “坤之泰”">​</a></h3><h3 id="林辭-10" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-10" aria-label="Permalink to “林辭”">​</a></h3><p>雷行相逐，無有攸息。戰於平陸，為夷所覆。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>震為雷、為逐、為戰，坤為平陸、為夷狄，坤死兌折，故曰為夷所覆。如衛懿公是也。</p><h3 id="坤之否" tabindex="-1">坤之否 <a class="header-anchor" href="#坤之否" aria-label="Permalink to “坤之否”">​</a></h3><h3 id="林辭-11" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-11" aria-label="Permalink to “林辭”">​</a></h3><p>六龍爭極，服在下飾。謹慎管鑰，結禁無出。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>乾為龍，數六，在上，故曰六龍爭極，乾為衣，坤為裳，故曰服。坤為下、為文，故曰下飾。坤閉，故曰管鑰，曰結禁，坤六四曰「括囊」，是其義也。○下，依宋元本，汲古作不。鑰，元本作鑰。</p><h3 id="坤之同人" tabindex="-1">坤之同人 <a class="header-anchor" href="#坤之同人" aria-label="Permalink to “坤之同人”">​</a></h3><h3 id="林辭-12" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-12" aria-label="Permalink to “林辭”">​</a></h3><p>長男少女，相向共語，福祿歡喜。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>通《師》。震為長男，巽為少女，大過以巽為女妻，故巽亦為少女，震為語，巽震同聲相應，故曰共語，又離上下兩兌口相對，明夷謂曰有言，亦共語也。震為福、為樂。○汲古本共語下有「析薪在克」四字，於上下語甚不協，宋元本無，從之。</p><h3 id="坤之大有" tabindex="-1">坤之大有 <a class="header-anchor" href="#坤之大有" aria-label="Permalink to “坤之大有”">​</a></h3><h3 id="林辭-13" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-13" aria-label="Permalink to “林辭”">​</a></h3><p>遷延惡人，使德不通。炎火為殃，禾稼大傷。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>離為惡人、為炎火、為殃，餘未詳。○炎火，從宋元本。汲古作災火。禾稼，宋元本作年榖，年，疑禾之訛，依汲古。</p><h3 id="坤之謙" tabindex="-1">坤之謙 <a class="header-anchor" href="#坤之謙" aria-label="Permalink to “坤之謙”">​</a></h3><h3 id="林辭-14" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-14" aria-label="Permalink to “林辭”">​</a></h3><p>修其翰翼，隨風向北。至虞夏國，與舜相得。年歲大樂，邑無盜賊。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>震為翰翼，坤為北，伏巽，故曰隨風向北。坤為國，震為帝王，故曰虞夏、曰舜。坤為年歲，震為樂，坤為邑，坎為盜賊，坎隱伏，故無盜賊。</p><h3 id="坤之豫" tabindex="-1">坤之豫 <a class="header-anchor" href="#坤之豫" aria-label="Permalink to “坤之豫”">​</a></h3><h3 id="林辭-15" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-15" aria-label="Permalink to “林辭”">​</a></h3><p>鉛刀攻玉，堅不可得。盡我筋力，胝繭為疾。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>艮堅在外為刀，坤柔故曰鉛刀，震為玉，艮為堅，胝繭者，足病，震為足，坎疾，故曰胝繭為疾。筋力，象是否為艮未詳。○胝，汲古誤眠，宋本作視，茲依元本。</p><h3 id="坤之隨" tabindex="-1">坤之隨 <a class="header-anchor" href="#坤之隨" aria-label="Permalink to “坤之隨”">​</a></h3><h3 id="林辭-16" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-16" aria-label="Permalink to “林辭”">​</a></h3><p>舉袂覆目，不見日月。衣衾簠簋，就長夜室。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>震為袂、為舉，艮為目、為日，兌為月，巽為伏，故曰覆目不見。震為衣衾、為簠簋，艮為室，兌為夜，蓋三至上互大過，大過死故就長夜室，言墓內無光，如長夜也。《禮記》：「齊大飢，黔敖設食於路，有蒙袂而來者，黔敖曰：『嗟，來食，』曰：『餘唯不食嗟來食，以至於此。』遂死。」《士喪禮》「幎目緇尺二寸」，註：幎目，覆目者也。即袂也。○袂，宋元本作被，依汲古。衾，依宋元本，俗本誤裳。</p><h3 id="坤之蠱" tabindex="-1">坤之蠱 <a class="header-anchor" href="#坤之蠱" aria-label="Permalink to “坤之蠱”">​</a></h3><h3 id="林辭-17" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-17" aria-label="Permalink to “林辭”">​</a></h3><p>賊仁傷德，天怒不福。斬刈宗社，失其邦國。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>巽為賊、為傷，震為怒，艮為大，艮手為斬刈，震為宗，艮為社，四至上艮震反覆，故曰斬刈宗社。艮為邦國，坎為失。○仁、大，從宋元本，汲古作賊人，作大怒非。</p><h3 id="坤之臨" tabindex="-1">坤之臨 <a class="header-anchor" href="#坤之臨" aria-label="Permalink to “坤之臨”">​</a></h3><h3 id="林辭-18" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-18" aria-label="Permalink to “林辭”">​</a></h3><p>白龍赤虎，戰鬬俱怒。蚩尤敗走，死於魚口。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>震為白、為龍，伏艮為虎，乾為赤，故曰白龍赤虎。震為戰、為怒，坤為惡，故曰蚩尤。兌毀故敗，震為走，故曰敗走。坤為死、為魚，兌為口。《湘中志》：「湘南有魚口灘」，唐李紳詩「洛陽城見梅迎雪，魚口橋逢雪送梅。」又兌亦為虎，兌納丁，故曰赤虎，亦通。</p><h3 id="坤之觀" tabindex="-1">坤之觀 <a class="header-anchor" href="#坤之觀" aria-label="Permalink to “坤之觀”">​</a></h3><h3 id="林辭-19" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-19" aria-label="Permalink to “林辭”">​</a></h3><p>北辰紫宮，衣冠中立。含和建德，常受天福。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>坤為北，艮為星辰、為宮，故曰北辰紫宮。《天文志》：「中宮曰紫宮，即紫微垣也。」坤為衣裳，艮為冠，居中五，故曰中立。伏乾為德、為天福。</p><h3 id="坤之噬嗑" tabindex="-1">坤之噬嗑 <a class="header-anchor" href="#坤之噬嗑" aria-label="Permalink to “坤之噬嗑”">​</a></h3><h3 id="林辭-20" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-20" aria-label="Permalink to “林辭”">​</a></h3><p>稷為堯使，西見王母。拜請百福，賜我喜子。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>震為稷、為帝、為行，故曰稷為堯使。坎為西，震為王，伏巽為母，故曰王母。艮手為拜，震為言、為請、為百福、為喜、為子，故曰喜子。○喜，汲古訛嘉，喜子者，《詩》「蠨蛸在戶」疏：蠨蛸，長腳蛛，俗呼為「喜子」，《荊楚歲時記》：「七月七日陳瓜菓乞巧，有喜子網於瓜則以為符。」</p><h3 id="坤之賁" tabindex="-1">坤之賁 <a class="header-anchor" href="#坤之賁" aria-label="Permalink to “坤之賁”">​</a></h3><h3 id="林辭-21" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-21" aria-label="Permalink to “林辭”">​</a></h3><p>三人異趣，反覆迷惑。一身五心，亂無所得。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>互震為人，數三，故曰三人，而三至上正覆震相背，故曰異趣、曰反覆，坎為迷惑也。艮為身，坎數一，故曰一身。坎為心，納戊數五，故曰五心，離為亂，離虛故無得。</p><h3 id="坤之剝" tabindex="-1">坤之剝 <a class="header-anchor" href="#坤之剝" aria-label="Permalink to “坤之剝”">​</a></h3><h3 id="林辭-22" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-22" aria-label="Permalink to “林辭”">​</a></h3><p>南山大玃，盜我媚妾。怯不敢逐，退而獨宿。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>艮山納丙，又為玃，故曰南山大玃，坤為我，伏兌為媚、為妾，坤柔為怯。震為逐，震覆為艮，故不逐。震為進，震覆則為退矣。坤為宿。《博物志》：「蜀南山有大玃，婦人好者，輒盜以去」。《廣韻》：「玃，大猿也。」</p><h3 id="坤之復" tabindex="-1">坤之復 <a class="header-anchor" href="#坤之復" aria-label="Permalink to “坤之復”">​</a></h3><h3 id="林辭-23" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-23" aria-label="Permalink to “林辭”">​</a></h3><p>眾鬼所逐，反作光怪。九身無頭，魂驚魄去，不可以居。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>坤為鬼、為眾，震為逐、為反、為玄黃，故曰光怪。坤為身，震納庚金，數九，故曰九身，乾為頭，乾伏，故曰無頭，伏乾為魂，坤為魄，震為驚，艮為居，艮覆故不可居。○鬼，從宋元本，汲古作九。光，宋元本作大，依汲古。</p><h3 id="坤之無妄" tabindex="-1">坤之無妄 <a class="header-anchor" href="#坤之無妄" aria-label="Permalink to “坤之無妄”">​</a></h3><h3 id="林辭-24" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-24" aria-label="Permalink to “林辭”">​</a></h3><p>延頸遠望，眯為目病。不見叔姬，使伯心憂。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>艮為頸、為望，離為目，大離故「目病」。《說文》：「眯，草入目中也。」震為草莽而與大離連，故曰眯。《易林》小學之精，用一字無不與卦象確切如此。震為姬，艮為叔，故曰叔姬，震為伯，巽為心、為憂。○眯汲古誤昧，依宋元本。</p><h3 id="坤之大畜" tabindex="-1">坤之大畜 <a class="header-anchor" href="#坤之大畜" aria-label="Permalink to “坤之大畜”">​</a></h3><h3 id="林辭-25" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-25" aria-label="Permalink to “林辭”">​</a></h3><p>典冊法書，藏在蘭臺。雖遭亂潰，獨不遇災。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>伏坤為文，故曰典冊法書，巽為伏、為香，故曰藏在蘭臺，艮為臺也，坤為亂潰、為災，乾福故無災，全用旁通象。</p><h3 id="坤之頤" tabindex="-1">坤之頤 <a class="header-anchor" href="#坤之頤" aria-label="Permalink to “坤之頤”">​</a></h3><h3 id="林辭-26" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-26" aria-label="Permalink to “林辭”">​</a></h3><p>自衛反魯，時不我與。冰炭異室，仁道隔塞。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>震為衛、為反，伏兌為魯，故曰自衛反魯，艮為時，坤為我、為冰，艮為火、為炭、為室，卦正覆艮相背，故曰異室，艮為道，坤閉故道隔塞。○我，依宋元本，汲古作可。非。</p><h3 id="坤之大過" tabindex="-1">坤之大過 <a class="header-anchor" href="#坤之大過" aria-label="Permalink to “坤之大過”">​</a></h3><h3 id="林辭-27" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-27" aria-label="Permalink to “林辭”">​</a></h3><p>瘤癭禿疥，為身瘡害。疾病癃殘，常不遠逮。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>通《頤》。艮為節，故曰瘤癭禿疥、曰瘡。坤為身、為死，故疾病癃殘，不能逮遠。○遠逮，汲古作屬遠，依宋元本。</p><h3 id="坤之坎" tabindex="-1">坤之坎 <a class="header-anchor" href="#坤之坎" aria-label="Permalink to “坤之坎”">​</a></h3><h3 id="林辭-28" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-28" aria-label="Permalink to “林辭”">​</a></h3><p>齊東郭盧，嫁於洛都。俊良美好，媒利過倍。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>《戰國策》：「韓子廬者，天下之良犬；東郭逡者，天下之狡兔」，《詩齊風》：「廬令令」，《毛傳》：「廬，田犬。」坎中爻艮為郭、為犬，震為東，伏巽為齊。又廬者：「黑色首為黔」，故曰齊東郭廬，舉一字於卦之象數皆合神已。艮為都，震為家，坎為河，故曰洛都。按：此林屢見嫁往也。《列子天瑞篇》：「列子居鄭圃四十年，人無視者，將嫁於衛」，又女子適人亦曰嫁，嫁於洛都者，往售於洛都也，故下雲媒利過倍，媒者，因也，言因犬得利也。○盧，汲古訛廬。齊東，宋本作東齊，茲依元本。</p><h3 id="坤之離" tabindex="-1">坤之離 <a class="header-anchor" href="#坤之離" aria-label="Permalink to “坤之離”">​</a></h3><h3 id="林辭-29" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-29" aria-label="Permalink to “林辭”">​</a></h3><p>齊魯爭言，戰於龍門。構怨連禍，三世不安。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>中爻巽齊兌魯，而二至五正反兩兌相背，兌為言，故曰齊魯爭言，伏坎中爻，震為戰、為龍，艮為門，故曰龍門。又坎為怨、為禍，離卦數三，故曰三世，離為亂，故不安。○連，依宋元本，汲古作結。</p><h3 id="坤之鹹" tabindex="-1">坤之鹹 <a class="header-anchor" href="#坤之鹹" aria-label="Permalink to “坤之鹹”">​</a></h3><h3 id="林辭-30" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-30" aria-label="Permalink to “林辭”">​</a></h3><p>膏澤肥壤，農人豐敞。利居長安，歷世無患。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>兌為膏、為澤，艮為壤，乾為肥，故曰肥壤，伏震為農人、為豐敞。坤為長安、為世，震樂故無患。○膏，從宋本。汲古、元本作芳。</p><h3 id="坤之恆" tabindex="-1">坤之恆 <a class="header-anchor" href="#坤之恆" aria-label="Permalink to “坤之恆”">​</a></h3><h3 id="林辭-31" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-31" aria-label="Permalink to “林辭”">​</a></h3><p>倉盈庾億，宜種黍稷。年豐歲熟，民得安息。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>通《益》。艮為倉庾，坤眾，故盈億，震為黍稷，坤為歲年、為民、為安息。詳《乾》之「師」。</p><h3 id="坤之遯" tabindex="-1">坤之遯 <a class="header-anchor" href="#坤之遯" aria-label="Permalink to “坤之遯”">​</a></h3><h3 id="林辭-32" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-32" aria-label="Permalink to “林辭”">​</a></h3><p>鴟鴞破斧，邦人危殆。賴旦忠德，轉禍為福，傾危復立。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>艮為鴟鴞，兌為斧，兌覆，故曰破斧。鴟鴞、破斧，《豳風》篇名，皆詠周公之德也。伏坤為邦，震為人，兌毀，故危殆，震為旦、為德，坤為禍，震為福。○旦，依汲古，宋元本皆作其。</p><h3 id="坤之大壯" tabindex="-1">坤之大壯 <a class="header-anchor" href="#坤之大壯" aria-label="Permalink to “坤之大壯”">​</a></h3><h3 id="林辭-33" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-33" aria-label="Permalink to “林辭”">​</a></h3><p>歲飢無年，虐政害民。乾溪驪山，秦楚結冤。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>通《觀》。坤為歲、為飢、為政、為民、為虐害，本卦兌為溪，下乾，故曰乾溪。《易》以乾為陵、為馬，故曰驪山，兌西為秦，震為叢木、為楚，驪山秦地，乾溪楚地，靈王死乾溪，始皇葬驪山，故曰結冤。</p><h3 id="坤之晉" tabindex="-1">坤之晉 <a class="header-anchor" href="#坤之晉" aria-label="Permalink to “坤之晉”">​</a></h3><h3 id="林辭-34" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-34" aria-label="Permalink to “林辭”">​</a></h3><p>挒潔堁堁，締結難解。嫫母衒嫁，媒不得坐，自為身禍。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>挒，捩也。潔，《說文》：「麻一專也」，艮為手，言以手捩麻、締結難解也。堁堁，塵起貌。坤為醜，故曰嫫母，離為見，故曰衒，坎為合、為媒，坤為身、為禍、為自。○挒，依汲古。潔，依局本，宋本作捯潔，元本作到椡潔。堁堁，依汲古比之大有校，各本皆作纍纍。</p><h3 id="坤之明夷" tabindex="-1">坤之明夷 <a class="header-anchor" href="#坤之明夷" aria-label="Permalink to “坤之明夷”">​</a></h3><h3 id="林辭-35" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-35" aria-label="Permalink to “林辭”">​</a></h3><p>娵訾開門，鶴鳴彈冠。章甫進用，舞韶和鸞。三人翼事，國無災患。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>候卦坤居亥為門，互震為開，故曰娵訾開門，娵訾，亥辰也，震為鶴、為鳴，覆艮為冠，艮手向下，故曰彈冠。章甫禮冠。震為進、為樂，故曰舞韶，為音故曰和鸞，鸞，鈴也。坎為和，坤文為鸞鳳，震為人，數三，又為翼，故曰三人翼事。翼，輔也，贊也。坤為事、為國，坎為憂患，震樂故無○娵訾，各本皆訛為「訾陬」，娵訾，亥辰名，坤象。字既顛倒，娵又作陬，似非。</p><h3 id="坤之家人" tabindex="-1">坤之家人 <a class="header-anchor" href="#坤之家人" aria-label="Permalink to “坤之家人”">​</a></h3><h3 id="林辭-36" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-36" aria-label="Permalink to “林辭”">​</a></h3><p>弟姊合居，與類相扶。願慕群醜，不離其友。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>長女、中女故曰弟姊，互坎為合，故曰合居，艮手為扶，離正反半艮，故曰相扶。《易》「家人」用半象，故亦用半象。互坎為願慕，離為醜，義本《離》上九也，重離故曰群醜，離坎為友，體連故不離，東漢人皆以陰與陰為友，豈知陰陽相遇方為友也。○弟姊合，汲古作姊妹本，茲從宋本。</p><h3 id="坤之睽" tabindex="-1">坤之睽 <a class="header-anchor" href="#坤之睽" aria-label="Permalink to “坤之睽”">​</a></h3><h3 id="林辭-37" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-37" aria-label="Permalink to “林辭”">​</a></h3><p>邯鄲反言，父兄生患。涉叔憂恨，卒死不還。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>坎，正反兌口相背，故曰反言、故為患、為憂恨。餘象多未詳，或用半象。《史記》：陳勝字涉，吳廣字叔，陳勝遣武臣徇趙，乃反楚，自立為趙王，陳王乃徙系武臣等家屬宮中，後涉、叔二人皆為下所殺。林似用其事。○叔，從宋元本，汲古訛此。又元本舊註以涉叔為陳涉，非；涉，陳勝字；叔，吳廣字也。</p><h3 id="坤之蹇" tabindex="-1">坤之蹇 <a class="header-anchor" href="#坤之蹇" aria-label="Permalink to “坤之蹇”">​</a></h3><h3 id="林辭-38" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-38" aria-label="Permalink to “林辭”">​</a></h3><p>二人逐兔，各爭有得。愛亡善走，多獲鹿子。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>震為人，三四及五上兩半震，故為二人，震為兔、為逐，故曰二人逐兔，兩震，故各爭有得。震為爭、為鹿、為子，艮為獲。愛亡者，言喜走也。亡，往也。○汲古有作其，愛亡作愛妾，均依宋元本。又二人宋元本作三人，依汲古。此皆用半象。</p><h3 id="坤之解" tabindex="-1">坤之解 <a class="header-anchor" href="#坤之解" aria-label="Permalink to “坤之解”">​</a></h3><h3 id="林辭-39" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-39" aria-label="Permalink to “林辭”">​</a></h3><p>北辰紫宮，衣冠立中。含和建德，常受天福。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>坎為北、為宮室、為和，震為辰、為衣、為建、為福，餘詳《觀》卦。</p><h3 id="坤之損" tabindex="-1">坤之損 <a class="header-anchor" href="#坤之損" aria-label="Permalink to “坤之損”">​</a></h3><h3 id="林辭-40" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-40" aria-label="Permalink to “林辭”">​</a></h3><p>拜跪請兔，不得其哺。俛首銜枚，低頭北去。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>艮為拜跪，震為言、為請，艮止，故曰請兔。兌為哺，坤虛，故不得哺。艮為首，坤下，故曰俛首、曰低頭，艮為小木、為枚，兌口，故曰銜枚，坤位北，震往，故北去。</p><h3 id="坤之益" tabindex="-1">坤之益 <a class="header-anchor" href="#坤之益" aria-label="Permalink to “坤之益”">​</a></h3><h3 id="林辭-41" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-41" aria-label="Permalink to “林辭”">​</a></h3><p>鶴盜我珠，逃於東隅。求之郭墟，不見所居。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>震為鶴、為珠，巽為盜，震往為逃、為東，故逃於東隅。艮為求、為郭，坤為墟，艮為居，巽伏，故不見。《說苑》：「桓公至郭墟，問郭之所以亡。」下二句用其事；又，此林屢見鶴盜珠，必有故實，今不能考。</p><h3 id="坤之夬" tabindex="-1">坤之夬 <a class="header-anchor" href="#坤之夬" aria-label="Permalink to “坤之夬”">​</a></h3><h3 id="林辭-42" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-42" aria-label="Permalink to “林辭”">​</a></h3><p>一簧兩舌，妄言謬訣。三姦成虎，曾母投杼。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>兌為簧、為舌，《詩》「巧言如簧」。乾卦數一，兌卦數二，故曰一簧兩舌。乾為言，兌口亦為言，乃兌言與乾言相背，故曰妄言謬訣，《夬》九四「聞言不信」，義與此同也。伏艮為虎，坤為姦，互三坤，故曰三姦成虎。坤為母，重坤，故曰曾母。曾層通。凡《易林》用一姓一名無不從象生，與《易》同也。艮為小木、為杼，艮手為投，故曰投杼。《戰國策》：今有人言市有虎，王信之乎？曰：「否。」三人言之，則信矣。《史記甘茂傳》：「昔魯人有與曾參同姓名者殺人，人告其母，織自若也；又一人告之，織自若也；又告之，其母遂投杼而走。」《古樂府》：「三夫成市虎，曾母投杼趨。」林正用其詞。○謬訣，從宋本，元本作謬語，汲古作謀訣，今謬從宋元本，訣從汲古，訣與舌韻。</p><h3 id="坤之姤" tabindex="-1">坤之姤 <a class="header-anchor" href="#坤之姤" aria-label="Permalink to “坤之姤”">​</a></h3><h3 id="林辭-43" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-43" aria-label="Permalink to “林辭”">​</a></h3><p>孤獨特處，莫與為旅。身日勞苦，使布五穀，陰陽順序。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>巽寡故曰孤獨、曰無旅，乾為日，通復。坤為身，萬物皆致役，故曰勞苦。巽為谷，卦數五，故曰五穀，巽為順。○依宋元本，汲古作「伯虎仲熊，德義洵美。使布五穀，陰陽順序。」</p><h3 id="坤之萃" tabindex="-1">坤之萃 <a class="header-anchor" href="#坤之萃" aria-label="Permalink to “坤之萃”">​</a></h3><h3 id="林辭-44" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-44" aria-label="Permalink to “林辭”">​</a></h3><p>褰衣涉河，水深漬罷。賴遇舟子，濟脫無他。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>坤為衣、為河，艮手為褰，故曰褰衣。坤水互大坎亦為水，故曰河、曰水深，坤為勞，故曰罷。罷，同疲，音婆，三至五伏震為舟、為子，震出故濟脫。○第二句各本多作「澗流浚多」，依訟之萃校。</p><h3 id="坤之升" tabindex="-1">坤之升 <a class="header-anchor" href="#坤之升" aria-label="Permalink to “坤之升”">​</a></h3><h3 id="林辭-45" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-45" aria-label="Permalink to “林辭”">​</a></h3><p>憑河登山，道路阻難，求事少便。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>坤為河，二陽臨坤水故曰憑河，本《泰》九二也，震為登、為道路，互大坎，故曰阻難，坤為事，艮為求，三至五艮覆，故少便。山象。《升》六四「王用享於岐山」，即以震為山。</p><h3 id="坤之困" tabindex="-1">坤之困 <a class="header-anchor" href="#坤之困" aria-label="Permalink to “坤之困”">​</a></h3><h3 id="林辭-46" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-46" aria-label="Permalink to “林辭”">​</a></h3><p>兔罝之容，不失其恭。和謙致樂，君子攸同。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>離為網、為罝，伏震為兔，故曰兔罝。坎為和，兌悅故曰致樂，伏艮為君子。《詩周南》：「肅肅兔罝」，《傳》「肅，敬也」，故曰不失其恭，林說詩意。</p><h3 id="坤之井" tabindex="-1">坤之井 <a class="header-anchor" href="#坤之井" aria-label="Permalink to “坤之井”">​</a></h3><h3 id="林辭-47" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-47" aria-label="Permalink to “林辭”">​</a></h3><p>三女求夫，伺候山隅。不見覆關，泣涕漣如。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>下巽，上互離，下互兌，故曰三女。坎為夫，本《左氏》也，二至四伏艮為山，艮止故曰伺候。艮為關，初至四正反艮，故曰復關，坎伏故不見。「坎為泣涕」二句，《詩氓》之語也。○如，從宋元，汲古作洳。</p><h3 id="坤之革" tabindex="-1">坤之革 <a class="header-anchor" href="#坤之革" aria-label="Permalink to “坤之革”">​</a></h3><h3 id="林辭-48" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-48" aria-label="Permalink to “林辭”">​</a></h3><p>螟蟲為賊，害我五穀。簞笥空虛，家無所食。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>互巽為蟲、為伏，故為螟，螟食苗心，言其冥冥難見。巽為賊、為谷，卦數五，兌毀，故曰害我五穀。伏坤為我，伏震為簞笥，坤為虛，伏艮為家，兌為食，坤虛，故無所食。語語本象與對象互用。○五，元本作黍，依宋本、汲古。簞笥，宋元本作中溜，依汲古。</p><h3 id="坤之鼎" tabindex="-1">坤之鼎 <a class="header-anchor" href="#坤之鼎" aria-label="Permalink to “坤之鼎”">​</a></h3><h3 id="林辭-49" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-49" aria-label="Permalink to “林辭”">​</a></h3><p>望尚阿衡，太宰周公。藩屏輔弼，福祿來同。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>離為望，巽為稱、為權，故曰望尚阿衡。望尚，太公；阿衡，伊尹也。伏震為周、為福祿，艮為藩屏。</p><h3 id="坤之震" tabindex="-1">坤之震 <a class="header-anchor" href="#坤之震" aria-label="Permalink to “坤之震”">​</a></h3><h3 id="林辭-50" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-50" aria-label="Permalink to “林辭”">​</a></h3><p>三牛生狗，以戌為母。荊夷上侵，姬伯出走。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>艮為牛，數三，故曰三牛，互艮為狗，震為生，故曰生狗。艮先天居戌方，戌狗，故曰以戌為母。震為草莽、為荊、為侵、為姬、為伯、為走，故曰姬伯出走。○第二句汲古作「以戌其母」，此從宋本。《開元佔經》引天鏡雲「牛生六畜，兵且起，其君不安。」</p><h3 id="坤之艮" tabindex="-1">坤之艮 <a class="header-anchor" href="#坤之艮" aria-label="Permalink to “坤之艮”">​</a></h3><h3 id="林辭-51" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-51" aria-label="Permalink to “林辭”">​</a></h3><p>塗遏道塞，求事不得。艮為道塗，艮止故遏塞，艮為求，坎陷不得。</p><h3 id="坤之漸" tabindex="-1">坤之漸 <a class="header-anchor" href="#坤之漸" aria-label="Permalink to “坤之漸”">​</a></h3><h3 id="林辭-52" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-52" aria-label="Permalink to “林辭”">​</a></h3><p>探懷得蚤，所願失道。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>艮為手、為探，坎為懷，巽蟲為蚤，坎為願、為失，艮為道。○宋元本得蚤下多「無有兇憂」、失道下多「善居漸好」四字，茲從汲古。</p><h3 id="坤之歸妹" tabindex="-1">坤之歸妹 <a class="header-anchor" href="#坤之歸妹" aria-label="Permalink to “坤之歸妹”">​</a></h3><h3 id="林辭-53" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-53" aria-label="Permalink to “林辭”">​</a></h3><p>飛樓屬道，趾多擾垣。居之不安，覆壓為患。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>艮為樓，震為覆艮，故曰飛樓。震為道、為趾，伏巽為垣，趾多攪垣者，言樓臨道，行人多攪亂不安也。艮為居，艮覆故不安，故覆壓坎為患也。○樓屬，從宋元本，汲古本作蟻遇，非。壓，宋本、汲古作厭，古通。</p><h3 id="坤之豐" tabindex="-1">坤之豐 <a class="header-anchor" href="#坤之豐" aria-label="Permalink to “坤之豐”">​</a></h3><h3 id="林辭-54" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-54" aria-label="Permalink to “林辭”">​</a></h3><p>義不勝情，以欲自傾。幾利危寵，折角摧頸。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>艮為角、為頸，上卦艮覆，故曰折角摧頸，又兌亦毀折也。幾利，言好利也。○幾利危寵，從元刊，宋本、汲古作幾危利寵。又寵疑為「躬」之訛字。</p><h3 id="坤之旅" tabindex="-1">坤之旅 <a class="header-anchor" href="#坤之旅" aria-label="Permalink to “坤之旅”">​</a></h3><h3 id="林辭-55" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-55" aria-label="Permalink to “林辭”">​</a></h3><p>潼滃蔚薈，扶首來會。津液下降，流潦滂沛。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>互大坎為雲，故曰潼滃蔚薈。艮為首、為扶，《後漢書輿服志》曰：「凡先合單紡為一系，四係為一扶，五扶為一首」，雲氣來會與絲縷集合同，故曰扶首。互大坎，故曰津液下降、流潦滂沛。下履之恆詞同，惟扶首作「膚寸」，何休註《公羊》雲：「側手為膚，按指為寸。」恆震為反艮，艮反，故象側手、象按指。蓋旅必作扶首，恆必作膚寸，方與卦象密切，近人不論卦象，概謂作扶首合，作膚寸非，疏矣。○扶首，元本作林木，非，依宋本、汲古。潦，宋本作淹，依元本、汲古。下，宋本作來，依汲古。</p><h3 id="坤之巽" tabindex="-1">坤之巽 <a class="header-anchor" href="#坤之巽" aria-label="Permalink to “坤之巽”">​</a></h3><h3 id="林辭-56" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-56" aria-label="Permalink to “林辭”">​</a></h3><p>白駒生芻，猗猗盛姝。赫喧君子，樂以忘憂。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>伏震為駒，巽白故曰白駒，巽為草莽，故為生芻、為長、為高，故曰猗猗盛姝。姝，美也。二四伏艮，艮為君子，赫喧者，容儀盛見。震為樂，故忘憂。○喧，《詩》作咺，《禮大學》作喧，宋本同，汲古訛喧。</p><h3 id="坤之兌" tabindex="-1">坤之兌 <a class="header-anchor" href="#坤之兌" aria-label="Permalink to “坤之兌”">​</a></h3><h3 id="林辭-57" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-57" aria-label="Permalink to “林辭”">​</a></h3><p>車馳人趍，捲甲相仇。齊魯寇戰，敗於犬丘。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>伏震為車、為人、為馳，艮為甲，艮伏故捲甲。巽齊兌魯，伏艮為犬、為丘，兌折，故敗於犬邱。地名，《左傳》：「鄭子然侵宋，取犬邱。」林但取卦象，不必與事相符。</p><h3 id="坤之渙" tabindex="-1">坤之渙 <a class="header-anchor" href="#坤之渙" aria-label="Permalink to “坤之渙”">​</a></h3><h3 id="林辭-58" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-58" aria-label="Permalink to “林辭”">​</a></h3><p>舉首望城，不見子貞，使我悔生。震為舉，坎為首，艮為城、為望，坎伏故不見。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>震為子，艮止為貞。《詩衛風》：「乘彼垝坦，以望復關。」子貞，蓋猶《鄭風》之不見子都、子充，不必有其人。</p><h3 id="坤之節" tabindex="-1">坤之節 <a class="header-anchor" href="#坤之節" aria-label="Permalink to “坤之節”">​</a></h3><h3 id="林辭-59" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-59" aria-label="Permalink to “林辭”">​</a></h3><p>龍鬬時門，失理傷賢。內畔外賊，則生禍難。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>震為龍，中爻正覆震，故曰鬬。艮為時、為門，故曰時門。《左傳昭二十九年》：「龍鬬於鄭時門之外」是也，艮為賢，坎為失、為賊，在外故曰外賊。震為生，坎為禍難，畔象未詳。○外，從宋本，汲古作生。</p><h3 id="坤之中孚" tabindex="-1">坤之中孚 <a class="header-anchor" href="#坤之中孚" aria-label="Permalink to “坤之中孚”">​</a></h3><h3 id="林辭-60" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-60" aria-label="Permalink to “林辭”">​</a></h3><p>安如泰山，福喜屢臻。雖有豺虎，不致危身。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>互艮為安、為山，震東故曰泰山。震為福喜、為至，艮為豺虎、為身，震樂故不危。○豺，依宋元本，汲古及常本作豹。致，汲古作敢，依宋元本。</p><h3 id="坤之小過" tabindex="-1">坤之小過 <a class="header-anchor" href="#坤之小過" aria-label="Permalink to “坤之小過”">​</a></h3><h3 id="林辭-61" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-61" aria-label="Permalink to “林辭”">​</a></h3><p>初憂後喜，與福為市。八佾列陳，飲御嘉友。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>互大坎為憂，震為喜、為後，故曰後喜。巽為市，震為舞。佾舞，行列也，行數、人數縱橫皆同。艮，九宮數八，上下正反震亦正反艮，故曰八佾。取象之能直同於《易》矣。震為陳列，兌口為飲，艮為友，艮陽在上，下乘二陰，《易》所謂「一人行則得其友也。」</p><h3 id="坤之既濟" tabindex="-1">坤之既濟 <a class="header-anchor" href="#坤之既濟" aria-label="Permalink to “坤之既濟”">​</a></h3><h3 id="林辭-62" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-62" aria-label="Permalink to “林辭”">​</a></h3><p>持刀操肉，對酒不食。夫行從軍，少子入獄，抱膝獨宿。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>艮為刀、為持，坎為肉，故持刀操肉。坎為酒，兌為食，艮止故不食。坎為夫、為眾，故為軍在外，故曰從軍。艮為小子，坎為獄，巽入，故曰小子入獄。艮為抱、為節，故曰抱膝。坎為宿，坎孤，故獨宿，除坎外皆用半象。○少，汲古作小，象同。</p><h3 id="坤之未濟" tabindex="-1">坤之未濟 <a class="header-anchor" href="#坤之未濟" aria-label="Permalink to “坤之未濟”">​</a></h3><h3 id="林辭-63" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-63" aria-label="Permalink to “林辭”">​</a></h3><p>陰衰老極，陽建其德。履離戴光，天下昭明。功業不長，蝦蟆大王。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>首二語言陽皆居上、陰居下也，半震為履，半艮為戴，重離故履離戴光，故天下昭明。震為功業，半震故不長。震為鳴、為王，故曰蝦蟆大王。《淮南子》雲：「騂牛被青紫入太廟用以求雨，不如黑蜧」，註：黑蜧即蝦蟇，古謂蝦蟇能求雨，大過之升雲：「蝦蟇群聚，從天請雨」，又隨之臨：「鼃池鳴呴，呼求水潦」，故《春秋繁露》雲：「春旱求雨，以甲乙日為蒼龍一丈八尺立於壇上，取五蝦蟇錯置社池中，方八尺、深二尺，具清酒膞脯拜跪陳詞」，又《淮南子說林訓》雲：「土龍芻狗，旱歲疾疫則為帝」，帝即大王，言當時尊貴也。功業不長，蝦蟇大王者，言如蝦蟇天旱用以求雨，尊貴一時，已則棄置也。○大，宋元本作代，依汲古。</p>',320)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
